// Independent normal-user host inventory. No process termination or registry writes.
using System;using System.IO;using System.Diagnostics;using System.Collections.Generic;using System.Linq;using System.Web.Script.Serialization;using Microsoft.Win32;
internal static class InspectCleanup {
    internal static int Main(string[] args){if(args.Length!=2)return 64;string evidence=Path.GetFullPath(args[0]),output=Path.GetFullPath(args[1]);if(!output.StartsWith(evidence+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)||File.Exists(output))return 65;var json=new JavaScriptSerializer();json.MaxJsonLength=32*1024*1024;
        var inventory=Process.GetProcesses();var ids=inventory.ToDictionary(p=>p.Id);var facts=new List<object>();var unreadable=new List<int>();var matching=new List<object>();string runtimeScope=Path.GetFullPath(".tmp/verification-lpac")+Path.DirectorySeparatorChar;
        foreach(var process in inventory){try{string image=process.MainModule.FileName;if(image!=null&&image.StartsWith(runtimeScope,StringComparison.OrdinalIgnoreCase))matching.Add(new{pid=process.Id,image=image});}catch{unreadable.Add(process.Id);}}
        if(matching.Count!=0)throw new InvalidOperationException("SYNTHETIC_RUNTIME_IMAGE_REMAINS");
        foreach(string directory in Directory.GetDirectories(Path.Combine(evidence,"attempts"))){string nonce=Path.GetFileName(directory);Guid parsed;if(!Guid.TryParseExact(nonce,"N",out parsed))throw new InvalidOperationException("ATTEMPT_NAME");var receipt=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(directory,"receipt.json")));string moniker=Convert.ToString(receipt["moniker"]);if(moniker!="specforge.regread."+nonce)throw new InvalidOperationException("MONIKER");var pidFacts=new List<object>();var seen=new HashSet<int>();DateTime finished=DateTime.Parse(Convert.ToString(receipt["finished_utc"])).ToUniversalTime();
            foreach(var line in File.ReadAllLines(Path.Combine(directory,"events.jsonl"))){var e=json.Deserialize<Dictionary<string,object>>(line);string name=(string)e["name"];if(name!="process_created_suspended"&&name!="control_created_suspended"&&name!="descendant_independently_verified")continue;var data=(Dictionary<string,object>)e["data"];int pid=Convert.ToInt32(data["pid"]);if(!seen.Add(pid))continue;bool reused=false;object current=null;
                if(ids.ContainsKey(pid)){var process=ids[pid];long currentCreated=process.StartTime.ToUniversalTime().ToFileTimeUtc();string image=process.MainModule.FileName;bool differentRecorded=data.ContainsKey("created_filetime")&&Convert.ToInt64(data["created_filetime"])!=currentCreated;bool newAfterFinish=DateTime.FromFileTimeUtc(currentCreated)>finished;if(!differentRecorded&&!newAfterFinish)throw new InvalidOperationException("OWNED_PID_PRESENT_REQUIRES_RECONCILIATION:"+pid);reused=true;current=new{created_filetime=currentCreated,image=image};}
                pidFacts.Add(new{pid=pid,present=false,query_succeeded=true,pid_reused=reused,current_identity=current});
            }
            string profile=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Packages",moniker);if(Directory.Exists(profile))throw new InvalidOperationException("PROFILE_PRESENT");string storage="Software\\Classes\\Local Settings\\Software\\Microsoft\\Windows\\CurrentVersion\\AppContainer\\Storage\\"+moniker;using(var key=Registry.CurrentUser.OpenSubKey(storage,false))if(key!=null)throw new InvalidOperationException("PRIVATE_REGISTRY_STORAGE_PRESENT");using(var key=Registry.CurrentUser.OpenSubKey("Software\\SpecForgeIsolationCanary-"+nonce,false))if(key!=null)throw new InvalidOperationException("HOST_CANARY_PRESENT");
            facts.Add(new{attempt=nonce,profile_present=false,private_storage_present=false,canary_key_present=false,processes=pidFacts.ToArray(),observed_utc=DateTime.UtcNow.ToString("o")});
        }
        File.WriteAllText(output,json.Serialize(new{utc=DateTime.UtcNow.ToString("o"),method="Successful Process.GetProcesses inventory; exact PID creation identities; exact owned profile/private-storage/fake-key paths in64bit registry",attempts=facts.ToArray(),matching_synthetic_images=matching.ToArray(),unreadable_image_pids=unreadable.ToArray(),limits="Protected unrelated images unreadable; owned PIDs absent or proven reused, plus native owner Job termination facts. Not general crash recovery acceptance.",inner_exit_code=0})+"\n",new System.Text.UTF8Encoding(false));Console.WriteLine("INDEPENDENT_HOST_CLEANUP attempts="+facts.Count+" profiles/private-storage/fake-keys/pids=ABSENT;EXIT=0");return 0;
    }
}
